use vstd::prelude::*;

verus! {

    /// The canonical “greedy” coin‐change for denominations [100,20,10,5,1].
    spec fn greedy(n: nat) -> nat {
        // How many 100’s?
        let c100 = n / 100;
        // Then how many 20’s in the remainder?
        let r100 = n % 100;
        let c20  = r100 / 20;
        // Then how many 10’s in the remainder?
        let r20  = r100 % 20;
        let c10  = r20 / 10;
        // Then how many 5’s in the remainder?
        let r10  = r20 % 10;
        let c5   = r10 / 5;
        // Finally the leftover 1’s:
        let r5   = r10 % 5;
        c100 + c20 + c10 + c5 + r5
    }

    /// Imperative implementation.  We require `n >= 0` since
    /// our spec is only for non‐negative amounts.
    fn solve(n: i8) -> (count: i8)
        requires
            n >= 0,
        ensures
            // upcast to `nat` for comparison against `greedy`
            count == (greedy(n as nat) as i8),
    {
        // We extract as many 100’s as we can, then 20’s, 10’s, 5’s, and 1’s.
        let mut amount = n;
        let mut count: i8 = 0;

        // 100‐unit notes
        let c100 = amount / 100;
        count += c100;
        amount %= 100;

        // 20‐unit notes
        let c20 = amount / 20;
        count += c20;
        amount %= 20;

        // 10‐unit notes
        let c10 = amount / 10;
        count += c10;
        amount %= 10;

        // 5‐unit coins
        let c5 = amount / 5;
        count += c5;
        amount %= 5;

        // 1‐unit coins (the remainder)
        count + amount
    }
}

fn main() {
    // just to make the binary complete
    let x = solve(127);
    assert!(x == 5); // 127 = 100 + 20 + 5 + 1 + 1
}